    if (internalLat === null || internalLng === null) {
      alert("蝣ｴ謇縺ｮ菴咲ｽｮ諠・ｱ・育ｷｯ蠎ｦ邨悟ｺｦ・峨′蜿門ｾ励〒縺阪∪縺帙ｓ縺ｧ縺励◆縲よ､懃ｴ｢縺九ｉ驕ｸ謚槭☆繧九°縲∝慍蝗ｳ縺九ｉ蜀榊ｺｦ縺願ｩｦ縺励￥縺縺輔＞縲・

