              <input
                type="date"
                value={visitedAt}
                onChange={(e) => setVisitedAt(e.target.value)}
                className="w-full border border-gray-300 dark:border-gray-700 rounded-md p-2 bg-white dark:bg-zinc-800 text-gray-900 dark:text-white placeholder-gray-400 dark:placeholder-gray-500 focus:outline-none focus:ring-2 focus:ring-blue-500"
              />
            </div>
          )}

          {/* 蠎怜錐/繧ｿ繧､繝医Ν */}
          <div>
            <label className="block text-sm font-medium mb-1 text-gray-700 dark:text-gray-300">蠎怜錐繝ｻ繧ｹ繝昴ャ繝亥錐・亥ｿ・茨ｼ・/label>
            <input
              type="text"
              value={title}
              onChange={(e) => setTitle(e.target.value)}
              required
              className="w-full border border-gray-300 dark:border-gray-700 rounded-md p-2 bg-white dark:bg-zinc-800 text-gray-900 dark:text-white placeholder-gray-400 dark:placeholder-gray-500 focus:outline-none focus:ring-2 focus:ring-blue-500"
              placeholder="萓・ 蛻昴ョ繝ｼ繝医〒陦後▲縺溘き繝輔ぉ"
            />
          </div>

          {/* 菴乗園 */}
          <div>
            <label className="block text-sm font-medium mb-1 text-gray-700 dark:text-gray-300">菴乗園</label>
            <input
              type="text"
              value={address}
              onChange={(e) => setAddress(e.target.value)}
              className="w-full border border-gray-300 dark:border-gray-700 rounded-md p-2 bg-white dark:bg-zinc-800 text-gray-900 dark:text-white placeholder-gray-400 dark:placeholder-gray-500 focus:outline-none focus:ring-2 focus:ring-blue-500"
              placeholder="譚ｱ莠ｬ驛ｽ貂玖ｰｷ蛹ｺ..."
            />
          </div>

          {/* URL */}
          <div>
            <label className="block text-sm font-medium mb-1 text-gray-700 dark:text-gray-300">URL・磯｣溘∋繝ｭ繧ｰ繧・・蠑上し繧､繝医↑縺ｩ・・/label>
            <input
              type="url"
              value={url}
              onChange={(e) => setUrl(e.target.value)}
              className="w-full border border-gray-300 dark:border-gray-700 rounded-md p-2 bg-white dark:bg-zinc-800 text-gray-900 dark:text-white placeholder-gray-400 dark:placeholder-gray-500 focus:outline-none focus:ring-2 focus:ring-blue-500"
              placeholder="https://..."
            />
          </div>

          {/* 繝｡繝｢ */}
          <div>
