              onChange={(e) => setMemo(e.target.value)}
              className="w-full border border-gray-300 dark:border-gray-700 rounded-md p-2 bg-white dark:bg-zinc-800 text-gray-900 dark:text-white placeholder-gray-400 dark:placeholder-gray-500 h-24 resize-none focus:outline-none focus:ring-2 focus:ring-blue-500"
              placeholder="讌ｽ縺励°縺｣縺滓昴＞蜃ｺ繧・∵ｬ｡陦後″縺溘＞逅・罰縺ｪ縺ｩ"
            />
          </div>

          {/* 逕ｻ蜒上い繝・・繝ｭ繝ｼ繝・*/}
          <div>
            <label className="block text-sm font-medium mb-1 text-gray-700 dark:text-gray-300">蜀咏悄繧定ｿｽ蜉</label>
            <input
              type="file"
              accept="image/*"
              onChange={(e) => {
                if (e.target.files && e.target.files.length > 0) {
                  const file = e.target.files[0];

                  // 逕ｻ蜒上・繝ｪ繧ｵ繧､繧ｺ繝ｻ蝨ｧ邵ｮ蜃ｦ逅・n                  const reader = new FileReader();
                  reader.onload = (event) => {
                    const img = new Image();
                    img.onload = () => {
                      const canvas = document.createElement("canvas");
                      const MAX_SIZE = 1000;
                      let width = img.width;
                      let height = img.height;

                      if (width > height) {
                        if (width > MAX_SIZE) {
                          height *= MAX_SIZE / width;
                          width = MAX_SIZE;
                        }
                      } else {
                        if (height > MAX_SIZE) {
                          width *= MAX_SIZE / height;
                          height = MAX_SIZE;
                        }
                      }

                      canvas.width = width;
                      canvas.height = height;
                      const ctx = canvas.getContext("2d");
                      ctx?.drawImage(img, 0, 0, width, height);

                      canvas.toBlob(
                        (blob) => {
                          if (blob) {
                            const compressedFile = new File([blob], file.name, {
                              type: "image/jpeg",
                              lastModified: Date.now(),
                            });
                            setImageFile(compressedFile);
                            setImageUrl(""); // Clear URL input when file is selected
                          }
                        },
